#!/usr/bin/env node
/**
 * Reproducible harvest of Princeton University Library's Figgy scanned maps.
 *
 * Discovery: the documented Blacklight JSON catalogue on figgy.princeton.edu,
 * filtered to `human_readable_type_ssim=Scanned Map` and
 * `rights_ssim=No Known Copyright` (the catalogue's own facet). The catalogue
 * payload deliberately does not carry a rights field per item, so the IIIF
 * Presentation 3 manifest is both the rights evidence and the metadata source:
 * its `rights` URI, `provider`, `metadata`, `navPlace` footprint, thumbnail and
 * image service are read per item.
 *
 * Rights gate (per manifest, never inferred from the catalogue facet):
 *   - rightsstatements.org NKC/1.0 (No Known Copyright) — the holding library's
 *     affirmative statement that copyright has not been established,
 *   - rightsstatements.org NoC-US/1.0,
 *   - Creative Commons CC0 1.0,
 *   - Creative Commons CC BY 4.0 (attribution is given on every record).
 * In Copyright, Copyright Not Evaluated, NoC-Other and every NC/ND licence stay
 * out. The verbatim rights URI and its official label are retained.
 *
 * Usage:
 *   node scripts/harvest-princeton.mjs                # cached, resumable, writes
 *   node scripts/harvest-princeton.mjs --refresh      # re-fetch pages/manifests
 *   node scripts/harvest-princeton.mjs --no-write     # report only
 *   node scripts/harvest-princeton.mjs --limit 50     # first N candidates (probe)
 */
import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { shardPath, shardUrl } from './catalogue.mjs';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const value = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/princeton');
const REFRESH = has('refresh');
const WRITE = !has('no-write');
const LIMIT = Number(value('limit', '0')) || 0;
const PAGE_SIZE = 100;
const CONCURRENCY = Math.max(1, Math.min(4, Number(value('concurrency', '3')) || 3));
const UA = 'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map catalogue)';
const API = 'https://figgy.princeton.edu/catalog.json';
const FILTER = 'f%5Bhuman_readable_type_ssim%5D%5B%5D=Scanned+Map&f%5Brights_ssim%5D%5B%5D=No+Known+Copyright';
const RETRIEVED = '2026-10-20';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function fetchJson(url, { attempts = 4 } = {}) {
  let last;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const res = await fetch(url, { headers: { accept: 'application/json', 'user-agent': UA } });
      if (res.ok) return await res.json();
      last = new Error(`${res.status} ${url}`);
      if (res.status !== 429 && res.status < 500) break;
    } catch (error) {
      last = error;
    }
    await sleep(500 * attempt);
  }
  throw last;
}

async function readJson(path) {
  return JSON.parse(await readFile(path, 'utf8'));
}

async function writeJson(path, body) {
  await mkdir(dirname(path), { recursive: true });
  const temp = `${path}.tmp-${process.pid}`;
  await writeFile(temp, JSON.stringify(body));
  await rename(temp, path);
}

async function cachedPage(page) {
  const path = resolve(CACHE, 'pages', `page-${page}.json`);
  if (!REFRESH) {
    try {
      return await readJson(path);
    } catch {}
  }
  const body = await fetchJson(`${API}?${FILTER}&per_page=${PAGE_SIZE}&page=${page}`);
  await writeJson(path, body);
  return body;
}

function manifestUrl(uuid) {
  return `https://figgy.princeton.edu/concern/scanned_maps/${uuid}/manifest`;
}

async function cachedManifest(uuid) {
  const path = resolve(CACHE, 'manifests', `${uuid}.json`);
  if (!REFRESH) {
    try {
      return await readJson(path);
    } catch {}
  }
  const body = await fetchJson(manifestUrl(uuid));
  await writeJson(path, body);
  return body;
}

/* ------------------------------------------------------------------ parsing */

/** IIIF label/value (`{"eng":["…"]}`, string, array or language map) → text. */
export function labelText(value) {
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) return value.map(labelText).filter(Boolean).join(' ').trim();
  if (value && typeof value === 'object') {
    if (typeof value['@value'] === 'string') return value['@value'].trim();
    const preferred = value.eng ?? value.en ?? value.none;
    if (preferred) return labelText(preferred);
    for (const entry of Object.values(value)) {
      const text = labelText(entry);
      if (text) return text;
    }
  }
  return '';
}

const RIGHTS = [
  {
    match: /^https?:\/\/rightsstatements\.org\/vocab\/NKC\/1\.0\/?$/i,
    label: 'No Known Copyright',
    basis: 'no-known-copyright',
  },
  {
    match: /^https?:\/\/rightsstatements\.org\/vocab\/NoC-US\/1\.0\/?$/i,
    label: 'No Copyright – United States',
    basis: 'no-copyright-us',
  },
  {
    match: /^https?:\/\/creativecommons\.org\/publicdomain\/zero\/1\.0\/?$/i,
    label: 'CC0 1.0 Public Domain Dedication',
    basis: 'cc0',
  },
  {
    match: /^https?:\/\/creativecommons\.org\/licenses\/by\/4\.0\/?$/i,
    label: 'Creative Commons Attribution 4.0 International',
    basis: 'cc-by',
  },
];

/**
 * The manifest's own rights URI is the gate. Returns `{uri,label,basis}` or
 * null; a rights URI we do not explicitly recognise is never assumed open.
 */
export function rightsOf(manifest) {
  const raw = manifest?.rights;
  const uri = typeof raw === 'string' ? raw.trim() : '';
  if (!uri) return null;
  const rule = RIGHTS.find((entry) => entry.match.test(uri));
  if (!rule) return null;
  return { uri, label: rule.label, basis: rule.basis };
}

/** All 4-digit publication years stated by a free-text date; none are invented. */
export function yearRange(value) {
  const years = [...String(value ?? '').matchAll(/(?<!\d)(1[4-9]\d{2}|20\d{2})(?!\d)/g)]
    .map((match) => Number(match[1]))
    .filter((year) => year >= 1400 && year <= 2100);
  if (years.length === 0) return { start: null, end: null };
  return { start: Math.min(...years), end: Math.max(...years) };
}

function positions(coordinates, out) {
  if (!Array.isArray(coordinates)) return;
  if (coordinates.length >= 2 && Number.isFinite(coordinates[0]) && Number.isFinite(coordinates[1])) {
    out.push([Number(coordinates[0]), Number(coordinates[1])]);
    return;
  }
  for (const child of coordinates) positions(child, out);
}

/**
 * The manifest's `navPlace` footprint as a WGS84 bbox. Only a single usable
 * footprint is accepted; a dateline-crossing or out-of-range polygon is
 * reported as no extent rather than flipped into a fake box.
 */
export function extentOf(manifest) {
  const place = manifest?.navPlace;
  if (!place || place.type !== 'FeatureCollection' || !Array.isArray(place.features)) return null;
  const points = [];
  for (const feature of place.features) positions(feature?.geometry?.coordinates, points);
  if (points.length < 3) return null;
  let west = Infinity;
  let east = -Infinity;
  let south = Infinity;
  let north = -Infinity;
  for (const [lon, lat] of points) {
    if (lon < -180 || lon > 180 || lat < -90 || lat > 90) return null;
    west = Math.min(west, lon);
    east = Math.max(east, lon);
    south = Math.min(south, lat);
    north = Math.max(north, lat);
  }
  if (!(west < east && south < north)) return null;
  return { west, east, south, north };
}

/** Manifest metadata → Map<lowercase label, string[]> without inventing values. */
export function metadataOf(manifest) {
  const map = new Map();
  for (const entry of Array.isArray(manifest?.metadata) ? manifest.metadata : []) {
    const label = labelText(entry?.label).toLowerCase();
    const text = labelText(entry?.value);
    if (!label || !text) continue;
    const list = map.get(label) ?? [];
    list.push(text);
    map.set(label, list);
  }
  return map;
}

function first(map, ...labels) {
  for (const label of labels) {
    const values = map.get(label);
    if (values?.length) return values[0];
  }
  return '';
}

function all(map, ...labels) {
  const out = [];
  for (const label of labels) {
    for (const value of map.get(label) ?? []) {
      if (value && !out.includes(value)) out.push(value);
    }
  }
  return out;
}

function clean(value) {
  return String(value ?? '')
    .replace(/<\/?[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Canvas image body/service and a bounded thumbnail from the same service. */
export function imageOf(manifest) {
  const canvas = Array.isArray(manifest?.items) ? manifest.items[0] : null;
  const annotation = canvas?.items?.[0];
  const body = annotation?.items?.[0]?.body ?? annotation?.body ?? null;
  const services = Array.isArray(body?.service) ? body.service : body?.service ? [body.service] : [];
  let service = services.map((entry) => (typeof entry === 'string' ? entry : entry?.['@id'] ?? entry?.id)).find((value) => typeof value === 'string' && /^https:\/\//.test(value)) ?? '';
  if (service.endsWith('/info.json')) service = service.slice(0, -'/info.json'.length);
  const thumbnail = (Array.isArray(manifest?.thumbnail) ? manifest.thumbnail : [])
    .map((entry) => (typeof entry === 'string' ? entry : entry?.id))
    .find((value) => typeof value === 'string' && /^https:\/\/[^/]*iiif-cloud\.princeton\.edu\//.test(value));
  return {
    service: service.replace(/\/+$/, ''),
    thumbnail:
      thumbnail ??
      (service ? `${service.replace(/\/+$/, '')}/full/!200,150/0/default.jpg` : ''),
  };
}

/**
 * One manifest → one catalogue record, or null when any required identity or
 * the rights gate fails. Titles, dates and creators are copied, not translated.
 */
export function recordOf(uuid, manifest) {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(uuid)) return null;
  const rights = rightsOf(manifest);
  if (!rights) return null;
  const meta = metadataOf(manifest);
  const title = clean(labelText(manifest?.label)) || clean(first(meta, 'title'));
  if (!title) return null;
  const { service, thumbnail } = imageOf(manifest);
  if (!service || !thumbnail) return null;
  const dateText = clean(first(meta, 'date', 'publication', 'issued'));
  const years = yearRange(dateText);
  const extent = extentOf(manifest);
  const creators = all(meta, 'creator', 'author', 'contributor', 'imported author').map(clean).filter(Boolean);
  const collections = all(meta, 'member of collections').map(clean).filter(Boolean);
  const ark = clean(first(meta, 'ark'));
  const record = {
    id: `princeton:${uuid}`,
    title,
    creators,
    providerId: 'princeton',
    institution: 'Princeton University Library',
    rights: `${rights.label} (${rights.uri})`,
    rightsUri: rights.uri,
    rightsBasis: rights.basis,
    recordUrl: `https://figgy.princeton.edu/catalog/${uuid}`,
    thumbnail,
    iiifManifest: manifestUrl(uuid),
    imageService: service,
    type: 'map',
    collection: collections.length ? collections.join(' / ') : 'Princeton University Library — Scanned Maps',
  };
  if (dateText) record.dateText = dateText;
  if (Number.isFinite(years.start)) {
    record.yearStart = years.start;
    record.yearEnd = years.end;
  } else {
    record.yearStart = null;
    record.yearEnd = null;
  }
  const publisher = clean(first(meta, 'publisher'));
  if (publisher) record.publisher = publisher;
  const language = clean(first(meta, 'language'));
  if (language) record.language = language;
  const scale = clean(first(meta, 'cartographic scale'));
  if (scale) record.scale = scale;
  const callNumber = clean(first(meta, 'call number'));
  if (callNumber) record.shelfmark = callNumber;
  if (ark) record.ark = ark;
  if (extent) {
    record.extent = extent;
    record.geo = { lat: (extent.south + extent.north) / 2, lon: (extent.west + extent.east) / 2 };
    record.geoNote = 'Footprint stated by the Princeton IIIF manifest navPlace; no image alignment is inferred.';
  } else {
    record.geoNote = 'The Princeton IIIF manifest does not state a footprint; no place or extent is inferred.';
  }
  return record;
}

/* ---------------------------------------------------------------- live check */

async function verify(records) {
  if (!records.length) return { checked: 0, samples: [] };
  const step = Math.max(1, Math.floor(records.length / 20));
  const sample = records.filter((_, index) => index % step === 0).slice(0, 20);
  const samples = [];
  for (const record of sample) {
    const status = async (url, method = 'GET') => {
      try {
        const res = await fetch(url, { method, headers: { 'user-agent': UA } });
        return { status: res.status, type: res.headers.get('content-type') };
      } catch (error) {
        return { status: 0, type: String(error?.message || error) };
      }
    };
    samples.push({
      id: record.id,
      manifest: await status(record.iiifManifest, 'HEAD'),
      thumbnail: await status(record.thumbnail, 'HEAD'),
      info: await status(`${record.imageService}/info.json`, 'HEAD'),
    });
    await sleep(120);
  }
  return { checked: samples.length, samples };
}

/* --------------------------------------------------------------------- main */

async function main() {
  const first = await cachedPage(1);
  const total = first.meta.pages.total_count;
  const pages = first.meta.pages.total_pages;
  console.log(`Princeton Figgy Scanned Map / No Known Copyright inventory: ${total} in ${pages} pages`);
  const documents = [...first.data];
  let next = 2;
  async function worker() {
    while (true) {
      const page = next++;
      if (page > pages) return;
      const body = await cachedPage(page);
      documents.push(...body.data);
      if (page % 10 === 0) console.log(`catalogue page ${page}/${pages}`);
      await sleep(80);
    }
  }
  await Promise.all(Array.from({ length: Math.min(3, CONCURRENCY) }, worker));

  const uuids = [...new Set(documents.map((document) => document?.id).filter(Boolean))];
  const candidates = LIMIT ? uuids.slice(0, LIMIT) : uuids;
  console.log(`Unique catalogue items: ${uuids.length}; fetching ${candidates.length} manifests`);

  const records = [];
  const withheld = {};
  const failed = [];
  let done = 0;
  let cursor = 0;
  async function manifestWorker() {
    while (true) {
      const index = cursor++;
      if (index >= candidates.length) return;
      const uuid = candidates[index];
      try {
        const manifest = await cachedManifest(uuid);
        const record = recordOf(uuid, manifest);
        if (record) records.push(record);
        else {
          const uri = typeof manifest?.rights === 'string' ? manifest.rights : '(no rights URI)';
          const reason = `rights/identity withheld: ${uri}`;
          withheld[reason] = (withheld[reason] || 0) + 1;
        }
      } catch (error) {
        failed.push({ uuid, error: String(error?.message || error) });
      }
      done += 1;
      if (done % 500 === 0) console.log(`manifests ${done}/${candidates.length} (kept ${records.length}, failed ${failed.length})`);
      await sleep(60);
    }
  }
  await Promise.all(Array.from({ length: CONCURRENCY }, manifestWorker));

  if (!records.length) throw new Error('No eligible Princeton records; leaving the catalogue unchanged.');
  records.sort((a, b) => (a.yearStart ?? Infinity) - (b.yearStart ?? Infinity) || a.id.localeCompare(b.id));
  const basis = {};
  for (const record of records) basis[record.rightsBasis] = (basis[record.rightsBasis] || 0) + 1;
  console.log(`Eligible Princeton records: ${records.length}`);
  console.log('Rights bases:', basis);
  console.log('Withheld:', Object.fromEntries(Object.entries(withheld).sort((a, b) => b[1] - a[1]).slice(0, 8)));
  console.log('Manifest failures:', failed.length);
  console.log('With an extent:', records.filter((record) => record.extent).length, 'with a year:', records.filter((record) => record.yearStart).length);

  const verification = await verify(records);
  console.log('Verification sample:', JSON.stringify(verification, null, 1).slice(0, 2000));

  const recordsPath = resolve(OUT, 'records.json');
  const sourcesPath = resolve(OUT, 'sources.json');
  const recordsDoc = await readJson(recordsPath);
  const sourcesDoc = await readJson(sourcesPath);
  const shard = shardUrl('princeton');
  recordsDoc.shards = [...new Set([...(recordsDoc.shards ?? []), shard])].sort();
  recordsDoc.records = recordsDoc.records.filter((record) => record.providerId !== 'princeton');
  recordsDoc.generatedAt = new Date().toISOString();
  recordsDoc.retrieved = RETRIEVED;
  recordsDoc.method = `${recordsDoc.method ? recordsDoc.method + ' ' : ''}Princeton University Library scanned maps are imported from the documented Figgy catalogue JSON and each item's IIIF Presentation 3 manifest (rights URI, metadata, footprint, thumbnail, image service); they are bundled in ${shard} and merged by the catalogue loader.`;
  recordsDoc.selection ??= {};
  recordsDoc.selection['princeton:figgy-scanned-maps'] = {
    considered: documents.length,
    candidates: candidates.length,
    kept: records.length,
    shard,
    rightsBasis: basis,
    withheld,
    failed: failed.slice(0, 50),
    failedCount: failed.length,
    rule:
      'Every Scanned Map in Princeton Figgy whose item manifest carries rightsstatements.org NKC/1.0 or NoC-US/1.0, CC0 1.0, or CC BY 4.0. Copyright Not Evaluated, In Copyright, NoC-Other and NC/ND licences are withheld; the catalogue facet is only discovery, the manifest rights URI is the gate. Undated items keep a null publication date; navPlace is the only extent source.',
    verification,
  };

  const provider = {
    id: 'princeton',
    name: 'Princeton University Library — Figgy',
    operator: 'Princeton University Library',
    homepage: 'https://figgy.princeton.edu/',
    home: 'https://figgy.princeton.edu/',
    institutions: ['Princeton University Library'],
    rights:
      'Each record retains its verbatim Princeton rights URI. Imported items carry rightsstatements.org NKC/1.0 (No Known Copyright) or NoC-US/1.0, CC0 1.0, or CC BY 4.0; Copyright Not Evaluated, In Copyright and NC/ND items are not imported. Attribution: Princeton University Library.',
    attribution: 'Princeton University Library',
    retrieved: RETRIEVED,
    api: {
      catalogue: 'https://figgy.princeton.edu/catalog.json',
      manifest: 'https://figgy.princeton.edu/concern/scanned_maps/{uuid}/manifest',
      image: 'https://iiif-cloud.princeton.edu/iiif/2/{imageId}',
      documentation: 'https://figgy.princeton.edu/',
    },
    apiHosts: ['figgy.princeton.edu', 'iiif-cloud.princeton.edu'],
    method:
      'Documented Blacklight JSON catalogue (Scanned Map, per_page 100, all pages) with per-item IIIF Presentation 3 manifests as the rights and metadata source; no decade, geography or record-count cap.',
    collections: [
      { id: 'historic-maps', name: 'Historic Maps', discovery: 'https://figgy.princeton.edu/catalog?f%5Bmember_of_collection_titles_ssim%5D%5B%5D=Historic+Maps' },
      { id: 'atlases', name: 'Atlases', discovery: 'https://figgy.princeton.edu/catalog?f%5Bmember_of_collection_titles_ssim%5D%5B%5D=Atlases' },
    ],
    verification,
  };
  sourcesDoc.providers = [...sourcesDoc.providers.filter((source) => source.id !== 'princeton'), provider];
  sourcesDoc.generatedAt = recordsDoc.generatedAt;

  const shardDoc = {
    generatedAt: recordsDoc.generatedAt,
    retrieved: RETRIEVED,
    providerId: 'princeton',
    method: 'Princeton Figgy Scanned Map manifests; per-item rights URI is the gate.',
    selection: recordsDoc.selection['princeton:figgy-scanned-maps'],
    records,
  };
  const coreBytes = Buffer.byteLength(JSON.stringify(recordsDoc));
  const shardBytes = Buffer.byteLength(JSON.stringify(shardDoc));
  console.log(
    `Catalogue would be ${recordsDoc.records.length} core + ${records.length} princeton records; ` +
      `core ${(coreBytes / 1024 / 1024).toFixed(2)} MiB, shard ${(shardBytes / 1024 / 1024).toFixed(2)} MiB`,
  );
  if (coreBytes > 24 * 1024 * 1024 || shardBytes > 24 * 1024 * 1024) {
    throw new Error('A catalogue asset exceeds 24 MiB; split it before writing.');
  }
  if (WRITE) {
    await mkdir(dirname(shardPath(OUT, shard)), { recursive: true });
    await writeFile(shardPath(OUT, shard), JSON.stringify(shardDoc) + '\n');
    await writeFile(recordsPath, JSON.stringify(recordsDoc) + '\n');
    await writeFile(sourcesPath, JSON.stringify(sourcesDoc, null, 2) + '\n');
    console.log('Wrote', OUT, 'and', shard);
  }
}

if (process.argv[1] && import.meta.url === new URL(`file://${resolve(process.argv[1])}`).href) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}

