/**
 * Princeton Figgy scanned-map import: rights gate, manifest parsing and the
 * committed shard.
 *
 * The catalogue facet is discovery only; these tests pin the rule that the
 * item's own IIIF `rights` URI decides reuse, and that an item without a real
 * image service is not turned into a placeholder record.
 */
import test from 'node:test';
import assert from 'node:assert/strict';

import {
  extentOf,
  imageOf,
  metadataOf,
  recordOf,
  rejectionOf,
  rightsOf,
  yearRange,
} from '../scripts/harvest-princeton.mjs';
import { readCatalogue } from '../scripts/catalogue.mjs';

const UUID = 'ba143341-e333-45aa-b5b9-682666142643';
const SERVICE = 'https://iiif-cloud.princeton.edu/iiif/2/26%2F22%2F7a%2F26227acca24944689819862943b59932%2Fintermediate_file';

function manifest(overrides = {}) {
  return {
    type: 'Manifest',
    label: { eng: ['Plano general de los Ferrocarriles Nacionales de Mexico'] },
    rights: 'http://rightsstatements.org/vocab/NKC/1.0/',
    provider: [{ id: 'https://library.princeton.edu', type: 'Agent', label: { en: ['Princeton University Library'] } }],
    metadata: [
      { label: { eng: ['Creator'] }, value: { eng: ['Ferrocarriles Nacionales de México'] } },
      { label: { eng: ['Date'] }, value: { eng: ['1910'] } },
      { label: { eng: ['Publisher'] }, value: { eng: ['[S.l.] : Ferrocarriles Nacionales de Mexico, 1910.'] } },
      { label: { eng: ['Language'] }, value: { eng: ['Spanish; Castilian'] } },
      { label: { eng: ['Call Number'] }, value: { eng: ['D Alcove 28, Drawer 17 HMC01.2122'] } },
      { label: { eng: ['Ark'] }, value: { eng: ['http://arks.princeton.edu/ark:/88435/dz010s583'] } },
      { label: { eng: ['Member Of Collections'] }, value: { eng: ['Historic Maps'] } },
    ],
    navPlace: {
      type: 'FeatureCollection',
      features: [
        {
          type: 'Feature',
          geometry: {
            type: 'Polygon',
            coordinates: [[[-118.6, 14.39], [-86.49, 14.39], [-86.49, 32.72], [-118.6, 32.72], [-118.6, 14.39]]],
          },
        },
      ],
    },
    thumbnail: [{ id: 'https://iiif-cloud.princeton.edu/iiif/2/de%2F5d%2F1f%2Fde5d1f67958e4fbe9e8537cc64350a08%2Fthumbnail/full/!200,150/0/default.jpg', type: 'Image', format: 'image/jpeg' }],
    items: [
      {
        type: 'Canvas',
        items: [
          {
            type: 'AnnotationPage',
            items: [
              {
                type: 'Annotation',
                body: {
                  type: 'Image',
                  format: 'image/jpeg',
                  service: [{ '@id': SERVICE, profile: 'http://iiif.io/api/image/2/level2.json' }],
                },
              },
            ],
          },
        ],
      },
    ],
    ...overrides,
  };
}

test('the manifest rights URI is the gate, never the catalogue facet', () => {
  assert.equal(rightsOf(manifest()).basis, 'no-known-copyright');
  assert.equal(rightsOf(manifest({ rights: 'http://rightsstatements.org/vocab/NoC-US/1.0/' })).basis, 'no-copyright-us');
  assert.equal(rightsOf(manifest({ rights: 'https://creativecommons.org/publicdomain/zero/1.0/' })).basis, 'cc0');
  assert.equal(rightsOf(manifest({ rights: 'https://creativecommons.org/licenses/by/4.0/' })).basis, 'cc-by');
  for (const rights of [
    'http://rightsstatements.org/vocab/CNE/1.0/',
    'http://rightsstatements.org/vocab/InC/1.0/',
    'http://rightsstatements.org/vocab/NoC-OKLR/1.0/',
    'https://creativecommons.org/licenses/by-nc/4.0/',
    'https://creativecommons.org/licenses/by-nd/4.0/',
    '',
    undefined,
  ]) {
    assert.equal(rightsOf(manifest({ rights })), null, `must reject ${rights}`);
  }
});

test('publication years are copied conservatively from the stated date', () => {
  assert.deepEqual(yearRange('1910'), { start: 1910, end: 1910 });
  assert.deepEqual(yearRange('1893-01-01'), { start: 1893, end: 1893 });
  assert.deepEqual(yearRange('ca. 1700'), { start: 1700, end: 1700 });
  assert.deepEqual(yearRange('1890-1900'), { start: 1890, end: 1900 });
  assert.deepEqual(yearRange('undated'), { start: null, end: null });
  assert.deepEqual(yearRange('1:50,000'), { start: null, end: null });
  assert.deepEqual(yearRange(''), { start: null, end: null });
});

test('navPlace becomes one honest bbox; invalid or dateline polygons do not', () => {
  assert.deepEqual(extentOf(manifest()), { west: -118.6, east: -86.49, south: 14.39, north: 32.72 });
  assert.equal(extentOf(manifest({ navPlace: null })), null);
  assert.equal(
    extentOf(manifest({ navPlace: { type: 'FeatureCollection', features: [{ geometry: { coordinates: [[[-190, 10], [10, 10], [10, 20], [-190, 10]]] } }] } })),
    null,
    'out-of-range longitude is rejected',
  );
  assert.equal(
    extentOf(manifest({ navPlace: { type: 'FeatureCollection', features: [{ geometry: { coordinates: [[[170, 10], [-170, 10], [-170, 20], [170, 10]]] } }] } })),
    null,
    'a dateline-crossing polygon is not flipped into a fake extent',
  );
});

test('a manifest record keeps the verbatim title, rights URI, identity and image service', () => {
  const record = recordOf(UUID, manifest());
  assert.ok(record, rejectionOf(UUID, manifest()));
  assert.equal(record.id, `princeton:${UUID}`);
  assert.equal(record.title, 'Plano general de los Ferrocarriles Nacionales de Mexico');
  assert.deepEqual(record.creators, ['Ferrocarriles Nacionales de México']);
  assert.equal(record.providerId, 'princeton');
  assert.equal(record.institution, 'Princeton University Library');
  assert.equal(record.rightsUri, 'http://rightsstatements.org/vocab/NKC/1.0/');
  assert.match(record.rights, /No Known Copyright/);
  assert.match(record.rights, /rightsstatements\.org\/vocab\/NKC\/1\.0/);
  assert.equal(record.recordUrl, `https://figgy.princeton.edu/catalog/${UUID}`);
  assert.equal(record.iiifManifest, `https://figgy.princeton.edu/concern/scanned_maps/${UUID}/manifest`);
  assert.equal(record.imageService, SERVICE);
  assert.match(record.thumbnail, /^https:\/\/iiif-cloud\.princeton\.edu\//);
  assert.equal(record.yearStart, 1910);
  assert.equal(record.yearEnd, 1910);
  assert.equal(record.type, 'map');
  assert.deepEqual(record.extent, { west: -118.6, east: -86.49, south: 14.39, north: 32.72 });
  assert.match(record.geoNote, /no image alignment is inferred/i);
  assert.ok(metadataOf(manifest()).get('call number').includes('HMC01.2122'));
});

test('an item without a real image service is withheld, not made a placeholder', () => {
  const imageless = manifest({ items: [], thumbnail: [] });
  assert.equal(recordOf(UUID, imageless), null);
  assert.match(rejectionOf(UUID, imageless), /no IIIF image service/);
  assert.match(rejectionOf(UUID, manifest({ rights: 'http://rightsstatements.org/vocab/InC/1.0/' })), /rights withheld/);
  assert.equal(imageOf(imageless).service, '');
});

test('the committed Princeton shard keeps the gate and the manifest identity', async () => {
  const catalogue = await readCatalogue();
  const records = catalogue.records.filter((record) => record.providerId === 'princeton');
  assert.ok(records.length >= 7000, `expected the harvested NKC corpus, found ${records.length}`);
  const hosts = new Set(['figgy.princeton.edu', 'iiif-cloud.princeton.edu']);
  for (const record of records) {
    assert.equal(record.providerId, 'princeton');
    assert.equal(record.institution, 'Princeton University Library');
    assert.ok(record.rightsUri, `${record.id}: rights URI`);
    assert.ok(rightsOf({ rights: record.rightsUri }), `${record.id}: rights URI must pass the documented gate`);
    assert.equal(new URL(record.recordUrl).hostname, 'figgy.princeton.edu');
    assert.equal(new URL(record.iiifManifest).hostname, 'figgy.princeton.edu');
    assert.equal(new URL(record.thumbnail).hostname, 'iiif-cloud.princeton.edu');
    assert.equal(new URL(record.imageService).hostname, 'iiif-cloud.princeton.edu');
    assert.ok(hosts.has(new URL(record.recordUrl).hostname));
    if (record.extent) {
      const { west, east, south, north } = record.extent;
      assert.ok(west < east && south < north, `${record.id}: valid bbox`);
      assert.ok(west >= -180 && east <= 180 && south >= -90 && north <= 90);
    }
    if (record.yearStart != null) assert.ok(record.yearStart <= record.yearEnd, `${record.id}: year order`);
  }
  const example = records.find((record) => record.id === `princeton:${UUID}`);
  assert.ok(example, 'the documented verification example is in the shard');
  assert.equal(example.yearStart, 1910);
  assert.match(example.title, /^Plano general de los Ferrocarriles Nacionales de Mexico$/);
});

